-- ═══════════════════════════════════════════════════════════════════════
-- SEED 02 — Catálogo de exercícios do sistema (138 exercícios)
--
-- Todos com created_by = NULL (exercício do sistema) e is_public = true.
-- Idempotente: o índice único uq_exercises_system_slug garante que rodar
-- de novo não duplica.
--
-- Distribuição: peito 16 · costas 17 · ombros 14 · bíceps 10 · tríceps 10
--               antebraço 4 · trapézio 4 · quadríceps 14 · posterior 7
--               glúteos 6 · panturrilha 5 · abdômen 14 · lombar 4
--               corpo inteiro 13
-- ═══════════════════════════════════════════════════════════════════════

insert into public.exercises
  (name_pt, name_en, slug, primary_muscle_group_id, equipment_id, mechanic,
   force_type, difficulty, tracking_type, is_unilateral, instructions)
select
  v.name_pt, v.name_en, v.slug, mg.id, eq.id,
  v.mechanic::exercise_mechanic,
  v.force::force_type,
  v.diff::experience_level,
  v.track::tracking_type,
  v.unilateral,
  v.instructions
from (values

