-- ═══════════════════════════════════════════════════════════════════════
-- Músculos secundários dos principais exercícios compostos
-- (usado na tela de detalhe do exercício)
-- ═══════════════════════════════════════════════════════════════════════
insert into public.exercise_muscle_groups (exercise_id, muscle_group_id, role)
select e.id, mg.id, 'secondary'::muscle_role
from (values
  ('supino-reto-barra','triceps'),          ('supino-reto-barra','shoulders'),
  ('supino-reto-halteres','triceps'),       ('supino-reto-halteres','shoulders'),
  ('supino-inclinado-barra','shoulders'),   ('supino-inclinado-barra','triceps'),
  ('supino-inclinado-halteres','shoulders'),('supino-inclinado-halteres','triceps'),
  ('supino-fechado','chest'),               ('supino-fechado','shoulders'),
  ('flexao-braco','triceps'),               ('flexao-braco','shoulders'),
  ('mergulho-paralelas','triceps'),         ('mergulho-paralelas','shoulders'),
  ('barra-fixa','biceps'),                  ('barra-fixa','forearms'),
  ('barra-fixa-supinada','biceps'),
  ('puxada-frontal','biceps'),
  ('remada-curvada-barra','biceps'),        ('remada-curvada-barra','lower_back'),
  ('remada-serrote','biceps'),
  ('remada-baixa-polia','biceps'),
  ('levantamento-terra','hamstrings'),      ('levantamento-terra','glutes'),
  ('levantamento-terra','lower_back'),      ('levantamento-terra','trapezius'),
  ('desenvolvimento-militar-barra','triceps'),
  ('desenvolvimento-halteres','triceps'),
  ('desenvolvimento-arnold','triceps'),
  ('remada-alta-barra','shoulders'),
  ('agachamento-livre','glutes'),           ('agachamento-livre','hamstrings'),
  ('agachamento-livre','lower_back'),
  ('agachamento-frontal','glutes'),         ('agachamento-frontal','abs'),
  ('agachamento-bulgaro','glutes'),
  ('agachamento-goblet','glutes'),
  ('leg-press-45','glutes'),
  ('afundo-halteres','glutes'),
  ('terra-romeno','glutes'),                ('terra-romeno','lower_back'),
  ('stiff-barra','glutes'),                 ('stiff-barra','lower_back'),
  ('good-morning','glutes'),                ('good-morning','lower_back'),
  ('elevacao-pelvica','hamstrings'),
  ('kettlebell-swing','glutes'),            ('kettlebell-swing','hamstrings'),
  ('thruster','quadriceps'),                ('thruster','shoulders'),
  ('clean-and-press','shoulders'),          ('clean-and-press','quadriceps'),
  ('burpee','chest'),                       ('burpee','quadriceps'),
  ('farmers-walk','trapezius'),
  ('ab-wheel','shoulders'),
  ('mountain-climber','shoulders')
) as v(ex_slug, mg_slug)
join public.exercises     e  on e.slug = v.ex_slug and e.created_by is null
join public.muscle_groups mg on mg.slug = v.mg_slug
on conflict (exercise_id, muscle_group_id) do nothing;
